<?php require_once __DIR__ . '/includes/header.php'; require_once __DIR__ . '/includes/ui_prompt.php'; require_once __DIR__ . '/includes/request_schema.php'; rm_schema($pdo); $sub=$_GET['sub']??'history'; if($sub==='dashboard')$sub='history'; $rmRoles=$_SESSION['user_data']['role_slugs']??[]; $rmRules=['admin'=>['dashboard','create','my-requests','approvals','fulfillment','requisitions','procurement','history'],'manager'=>['dashboard','create','my-requests','approvals','fulfillment','requisitions','procurement','history'],'department_head'=>['dashboard','create','my-requests','approvals','requisitions','history'],'housekeeping_officer'=>['dashboard','create','my-requests','history'],'maintenance_officer'=>['dashboard','create','my-requests','history'],'storekeeper','storekeper'=>['dashboard','fulfillment','requisitions','history'],'inventory_manager'=>['dashboard','fulfillment','requisitions','procurement','history'],'procurement_officer'=>['dashboard','requisitions','procurement','history'],'clinical_director'=>['dashboard','create','my-requests','approvals','history'],'managing_director'=>['dashboard','create','my-requests','approvals','history']]; foreach(['lab','lab_technician','imaging','radiologist','procedures','pharmacy','pharmacist','nurse','doctor','department','department_user'] as $rmC) $rmRules[$rmC]=$rmRules[$rmC]??['dashboard','create','my-requests','history']; $rmAllowed=[]; foreach($rmRoles as $r) $rmAllowed=array_merge($rmAllowed,$rmRules[$r]??[]); $rmAllowed=array_values(array_unique($rmAllowed)); if(!$rmAllowed)$rmAllowed=['dashboard','create','my-requests','history']; if(!in_array($sub,$rmAllowed,true))$sub=$rmAllowed[0]; $rmUid=(int)($_SESSION['user_id']??0); $rmGlobal=(bool)array_intersect($rmRoles,['admin','manager','inventory_manager','storekeeper','storekeper','procurement_officer','clinical_director','managing_director']); $rmIsNurse=in_array('nurse',$rmRoles,true)&&!array_intersect($rmRoles,rm_approver_roles()); $rmMyDept=$rmGlobal?0:(int)($_SESSION['user_data']['department_id']??0); if(!$rmGlobal&&!$rmMyDept&&$rmUid){$rmDeptQ=$pdo->prepare('SELECT department_id FROM users WHERE id=?');$rmDeptQ->execute([$rmUid]);$rmMyDept=(int)$rmDeptQ->fetchColumn();} $rmScoped=!$rmGlobal; $rmSelfApprove=(bool)array_intersect($rmRoles,['admin']); ?>
<style>.rm-page{color:#152238;max-width:1500px}.rm-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.rm-head h2{font-size:25px}.rm-head p{color:#6b7890;font-size:13px;margin-top:5px}.rm-btn{background:#1769e0;color:#fff;border:0;border-radius:7px;padding:9px 14px;font-weight:700;cursor:pointer}.rm-tabs{display:flex;gap:4px;flex-wrap:wrap;border-bottom:1px solid #e7ebf1;margin-bottom:20px}.rm-tabs a{padding:10px 11px;color:#6b7890;text-decoration:none;font-size:12px;font-weight:700;border-bottom:2px solid transparent}.rm-tabs a.active{color:#1769e0;border-color:#1769e0}.rm-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.rm-card{background:#fff;border:1px solid #e7ebf1;border-radius:10px;padding:16px}.rm-card small{display:block;color:#6b7890;font-size:11px;font-weight:700}.rm-card strong{display:block;font-size:24px;margin-top:7px}.rm-card h3{font-size:15px;margin-bottom:13px}.rm-table{width:100%;border-collapse:collapse;font-size:12px}.rm-table th,.rm-table td{padding:9px;border-bottom:1px solid #edf0f4;text-align:left}.rm-table th{background:#f6f8fb;font-size:10px;text-transform:uppercase;color:#6b7890}.rm-columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.rm-empty{text-align:center;padding:28px;color:#8a96a8}.rm-input{width:100%;box-sizing:border-box;border:1px solid #d8deea;border-radius:6px;padding:9px;font-size:13px}.rm-label{display:block;font-size:11px;font-weight:700;color:#6b7890;margin:10px 0 4px}.rm-status{padding:3px 8px;border-radius:15px;font-size:10px;font-weight:800;text-transform:capitalize;background:#eef1f5;color:#64748b}.rm-status.submitted,.rm-status.procurement{background:#fff2cf;color:#9a6900}.rm-status.pending_supervisor{background:#fff2cf;color:#9a6900}.rm-days{display:inline-block;padding:2px 7px;border-radius:12px;font-size:10px;font-weight:800;background:#eef1f5;color:#64748b}.rm-days.late{background:#fde8eb;color:#bd3d4b}.rm-btn{transition:transform .15s ease-out,opacity .15s ease-out}.rm-btn:active{transform:scale(.97)}@media(prefers-reduced-motion:reduce){.rm-btn{transition:none}.rm-btn:active{transform:none}}.rm-status.approved{background:#e5f0ff;color:#1d5fb5}.rm-status.fulfilled{background:#e2f6ed;color:#16845b}.rm-status.rejected,.rm-status.cancelled{background:#fde8eb;color:#bd3d4b}@media(max-width:900px){.rm-grid{grid-template-columns:repeat(2,1fr)}.rm-columns{grid-template-columns:1fr}}@media(max-width:600px){.rm-head{display:block}.rm-head button{margin-top:12px}.rm-grid{grid-template-columns:1fr 1fr}}
</style>
