<section id="rm-create" class="rm-screen" style="display:none"><div class="rm-card"><h3>Add new request</h3><div style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div><label class="rm-label">Department</label><select id="rm-dept" class="rm-input"></select></div><div><label class="rm-label">Required date</label><input id="rm-date" class="rm-input" type="date"></div><div><label class="rm-label">Priority</label><select id="rm-priority" class="rm-input"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></div><div><label class="rm-label">Purpose</label><input id="rm-purpose" class="rm-input"></div><div id="rm-sup-wrap" style="display:none"><label class="rm-label">Supervising doctor (approves first)</label><select id="rm-sup" class="rm-input"><option value="">Select doctor…</option></select></div><div style="grid-column:1/-1"><label class="rm-label">Comments</label><textarea id="rm-comments" class="rm-input" rows="2"></textarea></div></div><h3 style="margin-top:18px">Requested items</h3><table class="rm-table"><thead><tr><th>Item</th><th>Category</th><th>Quantity</th><th>Notes</th><th></th></tr></thead><tbody id="rm-items"><tr><td><select class="rm-input rm-item-name" onchange="rmItemPicked(this)"><option value="">Loading items…</option></select></td><td><input class="rm-input rm-item-cat" readonly placeholder="Auto"></td><td><input class="rm-input rm-item-qty" type="number" value="1" min="1"></td><td><input class="rm-input rm-item-note"></td><td><button class="rm-btn" onclick="rmAddItem()">+</button></td></tr></tbody></table><p style="font-size:11px;color:#8a96a8;margin-top:8px;">Items come from Inventory. The Storekeeper uses the same item to check stock and issue it.</p><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px"><button class="rm-btn" style="background:#64748b" onclick="rmSave(false)">Save Draft</button><button class="rm-btn" onclick="rmSave(true)">Submit Request</button></div></div></section>
