<script>window.rmRoles=<?php echo json_encode(array_values($rmRoles));?>;window.rmAllowed=<?php echo json_encode($rmAllowed);?>;window.rmUid=<?php echo (int)($_SESSION['user_id']??0);?>;window.rmMyDept=<?php echo (int)$rmMyDept;?>;window.rmScoped=<?php echo $rmScoped?'true':'false';?>;window.rmSelfApprove=<?php echo $rmSelfApprove?'true':'false';?>;window.rmApprovers=<?php echo json_encode(rm_approver_roles());?>;window.rmIsNurse=<?php echo $rmIsNurse?'true':'false';?>;window.rmReminderDays=<?php echo rm_reminder_days($pdo);?>;</script>
<script>
const rmBase=((typeof window.appBasePath!=='undefined'?window.appBasePath:(location.pathname.substring(0,location.pathname.lastIndexOf('/'))||''))+'/api.php?endpoint=requests/management');const rmSub='<?php echo $sub;?>';let rmRows=[];function rmEsc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function rmCall(action,body){let read=['list','dashboard','procurement','departments','items','supervisors'].includes(action)||action.startsWith('view');return fetch(rmBase+'&action='+action+(read&&body?'&'+new URLSearchParams(body):''),read?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined}).then(r=>r.json())}function rmStatus(s){return `<span class="rm-status ${s}">${rmEsc(s).replace('_',' ')}</span>`}let rmCurrentView='history';function rmShow(v){if(v==='dashboard')v='history';if(!(window.rmAllowed||[]).includes(v))return;rmCurrentView=v;document.querySelectorAll('.rm-screen').forEach(x=>x.style.display='none');if(v==='history'){document.getElementById('rm-dashboard').style.display='block';document.getElementById('rm-list').style.display='block';rmDash();rmLoad('history')}else if(v==='create'){document.getElementById('rm-create').style.display='block'}else{document.getElementById('rm-list').style.display='block';rmLoad(v)}}
async function rmLoad(view){let j=await rmCall(view==='procurement'?'procurement':'list',view==='approvals'?{status:'submitted,pending_supervisor'}:view==='fulfillment'?{status:'approved,partially_fulfilled'}:view==='requisitions'?{status:'procurement'}:view==='my-requests'?{mine:1}:view==='history'?{}:{});rmRows=j.data?.requests||j.data||[];if(j.data?.reminder_days)window.rmReminderDays=j.data.reminder_days;document.getElementById('rm-list-title').textContent=view==='history'?'History':view==='approvals'?'Approval Queue':view==='fulfillment'?'Stock Fulfillment':view==='requisitions'?'Requisitions':view==='procurement'?'Procurement Handoff':'My Requests';rmRender()}
function rmRender(){let q=(document.getElementById('rm-search')?.value||'').toLowerCase(),st=document.getElementById('rm-status')?.value||'';let rows=rmRows.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!st||x.status===st));document.getElementById('rm-list-body').innerHTML=rows.length?rows.map(x=>`<tr data-rm-id="${x.id}" data-rm-status="${x.status}" data-rm-req="${x.requested_by||0}" data-rm-sup="${x.supervisor_id||0}"><td><b>${rmEsc(x.request_no)}</b><br><span style="color:#8a96a8">${rmEsc(x.purpose||'')}</span></td><td>${rmEsc(x.requester_name||'')}</td><td>${rmEsc(x.department_name||'—')}</td><td>${x.item_count||x.items?.length||0}</td><td>${rmStatus(x.status)}${x.status==='rejected'&&x.rejection_reason?`<div style="font-size:11px;color:#b91c1c;margin-top:3px;">${rmEsc(x.rejection_reason)}</div>`:''}${x.status==='pending_supervisor'&&x.supervisor_name?`<div style="font-size:11px;color:#8a96a8;margin-top:3px;">Waiting for ${rmEsc(x.supervisor_name)}</div>`:''}</td><td>${rmDays(x)}</td><td><button class="rm-btn" onclick="rmView(${x.id})">View</button></td></tr>`).join(''):'<tr><td colspan="7" class="rm-empty">No requests found.</td></tr>';rmAddActions()}
function rmDays(x){if(x.days_pending==null)return '—';const n=+x.days_pending;return `<span class="rm-days${n>=(window.rmReminderDays||3)?' late':''}">${n} day${n===1?'':'s'}</span>`}function rmCanRemind(){return ['admin','storekeeper','storekeper','inventory_manager'].some(r=>(window.rmRoles||[]).includes(r))}function rmCanApprove(){return (window.rmApprovers||[]).some(r=>(window.rmRoles||[]).includes(r))}function rmCanFulfill(){return ['admin','manager','inventory_manager','storekeeper','storekeper'].some(r=>(window.rmRoles||[]).includes(r))}function rmAddActions(){const canApprove=rmCanApprove(),canFulfill=rmCanFulfill();document.querySelectorAll('#rm-list-body tr[data-rm-id]').forEach(r=>{let id=r.dataset.rmId,s=r.dataset.rmStatus,cell=r.lastElementChild,req=+r.dataset.rmReq,self=req===+window.rmUid;const supMine=s==='pending_supervisor'&&+r.dataset.rmSup===+window.rmUid;cell.style.display='flex';cell.style.flexWrap='wrap';cell.style.gap='6px';if(supMine)cell.insertAdjacentHTML('beforeend',` <button class="rm-btn" style="background:#16845b" onclick="rmSupApprove(${id})">Approve (supervisor)</button> <button class="rm-btn" style="background:#bd3d4b" onclick="rmReject(${id})">Reject</button>`);if((s==='submitted'||s==='pending_supervisor')&&rmCanRemind())cell.insertAdjacentHTML('beforeend',` <button class="rm-btn" style="background:#9a6900" onclick="rmRemind(${id})">Remind approver</button>`);if(s==='submitted'&&canApprove&&(!self||window.rmSelfApprove))cell.insertAdjacentHTML('beforeend',` <button class="rm-btn" style="background:#16845b" onclick="rmApprove(${id})">Approve</button>`);if(s==='submitted'&&canApprove&&!self)cell.insertAdjacentHTML('beforeend',` <button class="rm-btn" style="background:#bd3d4b" onclick="rmReject(${id})">Reject</button>`);if((s==='approved'||s==='partially_fulfilled')&&canFulfill)cell.insertAdjacentHTML('beforeend',` <button class="rm-btn" onclick="rmFulfill(${id})">Fulfill</button>`);if(s==='partially_fulfilled'&&canFulfill)cell.insertAdjacentHTML('beforeend',` <button class="rm-btn" onclick="rmProcure(${id})">Procurement</button>`)})}
async function rmDash(){let j=await rmCall('dashboard'),d=j.data||{};document.getElementById('rm-total').textContent=d.stats?.total||0;document.getElementById('rm-pending').textContent=d.stats?.pending||0;document.getElementById('rm-proc').textContent=d.stats?.procurement||0;document.getElementById('rm-full').textContent=d.stats?.fulfilled||0;}
let rmItems=[];function rmItemOptions(){return '<option value="">Select item…</option>'+rmItems.map(x=>`<option value="${x.id}" data-name="${rmEsc(x.name)}" data-cat="${rmEsc(x.category_name||'')}">${rmEsc(x.name)}${x.uom_abbr?' ('+rmEsc(x.uom_abbr)+')':''} — ${+x.in_stock>0?(+x.in_stock).toLocaleString()+' in stock':'(out of stock)'}</option>`).join('')}function rmFillItemSelects(){document.querySelectorAll('.rm-item-name').forEach(s=>{if(s.options.length<2)s.innerHTML=rmItemOptions()})}function rmItemPicked(sel){let o=sel.selectedOptions[0];sel.closest('tr').querySelector('.rm-item-cat').value=o?.dataset.cat||''}
async function rmSave(submit){let items=[...document.querySelectorAll('#rm-items tr')].map(r=>{let s=r.querySelector('.rm-item-name'),o=s.selectedOptions[0];return {item_id:o?.value?+o.value:null,item_name:o?.dataset.name||'',item_category:r.querySelector('.rm-item-cat').value,quantity:r.querySelector('.rm-item-qty').value,notes:r.querySelector('.rm-item-note').value}}).filter(x=>x.item_id||x.item_name);if(!items.length)return alert('Select at least one item.');if(window.rmIsNurse&&submit&&!document.getElementById('rm-sup').value)return alert('Select the supervising doctor.');let j=await rmCall('create',{department_id:document.getElementById('rm-dept').value,required_date:document.getElementById('rm-date').value,purpose:document.getElementById('rm-purpose').value,comments:document.getElementById('rm-comments').value,priority:document.getElementById('rm-priority').value,supervisor_id:document.getElementById('rm-sup').value,items,submit});alert(j.message);if(j.success)location.href='requests.php?module=requests&sub=my-requests'}function rmAddItem(){let tr=document.createElement('tr');tr.innerHTML=`<td><select class="rm-input rm-item-name" onchange="rmItemPicked(this)">${rmItemOptions()}</select></td><td><input class="rm-input rm-item-cat" readonly placeholder="Auto"></td><td><input class="rm-input rm-item-qty" type="number" value="1" min="1"></td><td><input class="rm-input rm-item-note"></td><td><button class="rm-btn" onclick="this.closest('tr').remove()">×</button></td>`;document.getElementById('rm-items').appendChild(tr)}
function rmClose(){document.getElementById('rm-modal').style.display='none'}function rmRefresh(){if(rmCurrentView==='history'){rmDash();rmLoad('history')}else rmLoad(rmCurrentView)}
async function rmView(id){let j=await rmCall('view&id='+id);if(!j.success)return alert(j.message);const x=j.data||{},self=+x.requested_by===+window.rmUid;document.getElementById('rm-modal-title').textContent=x.request_no||'Request';document.getElementById('rm-modal-sub').innerHTML=rmStatus(x.status)+' &nbsp;·&nbsp; '+rmEsc(x.department_name||'—')+' &nbsp;·&nbsp; Requested by '+rmEsc(x.requester_name||'—');const items=(x.items||[]).map(i=>`<tr><td>${rmEsc(i.item_name)}</td><td>${rmEsc(i.item_category||'—')}</td><td style="text-align:right">${(+i.quantity_requested||0).toLocaleString()}</td><td style="text-align:right">${(+i.quantity_issued||0).toLocaleString()}</td><td style="text-align:right;color:${+i.shortage>0?'#b91c1c':'#64748b'}">${(+i.shortage||0).toLocaleString()}</td></tr>`).join('');const hist=(x.history||[]).map(h=>`<div style="padding:7px 0;border-top:1px solid #eef1f5;font-size:12px;"><b style="text-transform:capitalize">${rmEsc(h.action)}</b> <span style="color:#6b7890">${rmEsc(String(h.from_status||'').replace(/_/g,' '))}${h.from_status?' → ':''}${rmEsc(String(h.to_status||'').replace(/_/g,' '))}</span><div style="color:#8a96a8;font-size:11px;">${rmEsc(h.user_name||'System')} · ${rmEsc(h.created_at||'')}${h.comment?' — '+rmEsc(h.comment):''}</div></div>`).join('');document.getElementById('rm-modal-body').innerHTML=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:14px;font-size:12px;"><div><div class="rm-label" style="margin-top:0">Purpose</div><b>${rmEsc(x.purpose||'—')}</b></div><div><div class="rm-label" style="margin-top:0">Priority</div><b style="text-transform:capitalize">${rmEsc(x.priority||'normal')}</b></div><div><div class="rm-label" style="margin-top:0">Required date</div><b>${rmEsc(x.required_date||'—')}</b></div><div><div class="rm-label" style="margin-top:0">Comments</div><b>${rmEsc(x.comments||'—')}</b></div></div><h4 style="font-size:13px;margin:0 0 6px;">Items</h4><div style="overflow:auto"><table class="rm-table"><thead><tr><th>Item</th><th>Category</th><th style="text-align:right">Requested</th><th style="text-align:right">Issued</th><th style="text-align:right">Shortage</th></tr></thead><tbody>${items||'<tr><td colspan="5" class="rm-empty">No items.</td></tr>'}</tbody></table></div><h4 style="font-size:13px;margin:16px 0 6px;">Approval history</h4><div>${hist||'<div style="color:#8a96a8;font-size:12px;">No history yet.</div>'}</div>`;let actions='';if(x.status==='pending_supervisor'&&+x.supervisor_id===+window.rmUid)actions+=`<button class="rm-btn" style="background:#16845b" onclick="rmSupApprove(${x.id})">Approve (supervisor)</button><button class="rm-btn" style="background:#bd3d4b" onclick="rmReject(${x.id})">Reject</button>`;if(['submitted','pending_supervisor'].includes(x.status)&&rmCanRemind())actions+=`<button class="rm-btn" style="background:#9a6900" onclick="rmRemind(${x.id})">Remind approver</button>`;if(x.status==='submitted'&&rmCanApprove()&&(!self||window.rmSelfApprove))actions+=`<button class="rm-btn" style="background:#16845b" onclick="rmApprove(${x.id})"><i class="fas fa-check"></i> Approve</button>`;if(x.status==='submitted'&&rmCanApprove()&&!self)actions+=`<button class="rm-btn" style="background:#bd3d4b" onclick="rmReject(${x.id})"><i class="fas fa-times"></i> Reject</button>`;if(['approved','partially_fulfilled'].includes(x.status)&&rmCanFulfill())actions+=`<button class="rm-btn" style="background:#16845b" onclick="rmFulfill(${x.id})">Check / Fulfill stock</button>`;if(x.status==='partially_fulfilled'&&rmCanFulfill())actions+=`<button class="rm-btn" style="background:#9a6900" onclick="rmProcure(${x.id})">Hand to Procurement</button>`;if(!['fulfilled','cancelled','rejected'].includes(x.status)&&(self||(window.rmRoles||[]).includes('admin')))actions+=`<button class="rm-btn" style="background:#64748b" onclick="rmCancel(${x.id})">Cancel request</button>`;document.getElementById('rm-modal-actions').innerHTML=actions||'<span style="font-size:12px;color:#8a96a8;">No actions available for your role.</span>';document.getElementById('rm-modal').style.display='flex'}
async function rmSupApprove(id){if(!confirm('Approve this request as supervisor? It then goes to final approval.'))return;let j=await rmCall('supervisor_approve',{id});alert(j.message);if(j.success){rmClose();rmRefresh()}}async function rmRemind(id){let j=await rmCall('remind',{id});alert(j.message);if(j.success){rmClose();rmRefresh()}}async function rmApprove(id){if(!confirm('Approve this request?'))return;let j=await rmCall('approve',{id});alert(j.message);if(j.success){rmClose();rmRefresh()}}async function rmReject(id){let c=await uiPrompt('Rejection reason:','',{title:'Reject request',required:true,requiredMessage:'Reason required.',placeholder:'Reason (required)',okLabel:'Reject'});if(c===null)return;let j=await rmCall('reject',{id,comment:c});alert(j.message);if(j.success){rmClose();rmRefresh()}}async function rmCancel(id){if(!confirm('Cancel this request?'))return;let j=await rmCall('cancel',{id});alert(j.message);if(j.success){rmClose();rmRefresh()}}async function rmFulfill(id){if(!confirm('Issue available stock for this request?'))return;let j=await rmCall('fulfill',{id});alert(j.message);if(j.success){rmClose();rmRefresh()}}async function rmProcure(id){let j=await rmCall('create_requisition',{id});alert(j.message);if(j.success){rmClose();rmRefresh()}}
async function rmLoadSupervisors(){const d=document.getElementById('rm-dept').value,s=document.getElementById('rm-sup');s.innerHTML='<option value="">Select doctor…</option>';if(!d)return;const j=await rmCall('supervisors',{department_id:d});(j.data||[]).forEach(x=>s.insertAdjacentHTML('beforeend',`<option value="${x.id}">${rmEsc(x.name)}</option>`));if(!(j.data||[]).length)s.innerHTML='<option value="">No doctor in this department</option>'}
async function rmInit(){let [d,it]=await Promise.all([rmCall('departments'),rmCall('items')]);rmItems=it.data||[];const deptSel=document.getElementById('rm-dept');deptSel.innerHTML='<option value="">Select department</option>'+(d.data||[]).map(x=>`<option value="${x.id}">${rmEsc(x.name)}</option>`).join('');if(window.rmScoped&&window.rmMyDept){deptSel.value=String(window.rmMyDept);deptSel.disabled=true}rmFillItemSelects();if(window.rmIsNurse){document.getElementById('rm-sup-wrap').style.display='block';deptSel.addEventListener('change',rmLoadSupervisors);rmLoadSupervisors()}document.getElementById('rm-date').value=new Date().toISOString().slice(0,10);rmShow(rmSub);document.getElementById('rm-search')?.addEventListener('input',rmRender);document.getElementById('rm-status')?.addEventListener('change',rmRender)}rmInit();
</script>

